    "context": "To use the MIDI features in Pro-C 2, create a new MIDI track and set its output to the Pro-C 2 instance you have just created. (The VST 3 version of Pro-C 2 can be found in the Dynamics section.) Logic Pro Choose an empty insert slot on one of your audio tracks, instrument tracks or buses and select FabFilter Pro-C 2 from the pop-up menu. You will find FabFilter Pro-C 2 in the Audio Units > FabFilter section (named FF Pro-C 2).",
    "contextZh": "要在 Pro-C 2 中使用 MIDI 功能，请新建一条 MIDI 轨道，并将其输出设置为你刚刚创建的 Pro-C 2 实例。（Pro-C 2 的 VST 3 版本可以在动态处理分类中找到。）Logic Pro：在音频轨道、乐器轨道或总线上选择一个空插入槽，从弹出菜单中选择 FabFilter Pro-C 2。你可以在 Audio Units > FabFilter 分类下找到 FabFilter Pro-C 2（名称为 FF Pro-C 2）。",
