    "example": "例子：Pro-C 2 的显示与计量部分包括电平显示、拐点显示等。",
    "context": "It consists of the following elements: Level display The animated level display shows you the incoming and processed audio signals together with the gain reduction. It helps you detemine the correct compressor settings. You can hide the level display with the Display button. This will also hide the knee display and change the vertical level meters to horizontal ones, making Pro-C 2 look and feel more like a traditional compressor. See Displays and metering.",
    "contextZh": "它由以下元素组成：电平显示 动态电平显示会向你展示输入和经过处理的音频信号以及增益衰减。它有助于你确定正确的压缩器设置。你可以使用显示按钮隐藏电平显示。这也会隐藏拐点显示，并将垂直电平表变为水平电平表，使 Pro-C 2 的外观和感觉更像传统的压缩器。参见“显示与计量”。",
