    "example": "例子：在贝斯压缩中，较短的释放时间能让每个音符的压缩独立恢复。",
    "context": "To begin, choose fast attack and release times, put the ratio to a gentle setting (like 4:1) and bring down the threshold to make compression audible. Adjust the parameters until you have the desired effect. Have fun! Next: Using FabFilter Pro-C 2 See Also Manual installation VST plug-in versions Overview The interface of FabFilter Pro-C 2 is designed to be easy to use while providing all necessary information and controls.",
