    "context": "Resize and Full Screen mode The Resize button at the far right of the bottom bar selects between various interface sizes. In addition, click the Full Screen button at the right top corner of the interface to let Pro-C 2 fill the entire screen. See Full Screen mode and resizing. Presets, undo, A/B, help With the preset buttons, you can easily browse through the factory presets or save your own settings so you can re-use them in other songs.",
    "contextZh": "调整大小与全屏模式。底部栏最右侧的调整大小按钮用于在各种界面尺寸之间进行选择。此外，点击界面右上角的全屏按钮，可让 Pro-C 2 填满整个屏幕。参见「全屏模式与调整大小」。预设、撤销、A/B 对比、帮助。通过预设按钮，你可以轻松浏览出厂预设，或保存自己的设置，以便在其他歌曲中重复使用。",
