    "example": "例子：在调整音量旋钮时，用这种方法可以精确到 0.1 dB 的变化。",
    "context": "By moving the mouse cursor further away from the knob while dragging it, you can make precise adjustments. 3. Mouse wheel mode Perhaps the easiest way to make adjustments is by using the mouse wheel when you hover over a knob. This mode works for all the knobs and possible panning rings. (On Windows, you might need to click in the plug-in interface first to make sure it is the active window.) 4. Text entry mode Double-click a knob to enter an exact value using the keyboard.",
