    "context": "The moment you move the mouse cursor over a knob, a parameter value display will pop up, which shows the name and the current value of the parameter. All knobs support four ways of control: 1. Vertical mode Click on the center area of a knob and drag up or down to rotate it. The knob reacts to the speed with which you are dragging, so if you move the mouse slowly, you make precise adjustments. 2. Rotate mode Grab the arrow of the knob and drag it around.",
    "contextZh": "当你把鼠标光标移到旋钮上时，会弹出一个参数值显示，展示参数的名称和当前值。所有旋钮支持四种控制方式：1. 垂直模式：点击旋钮的中心区域并上下拖动来旋转它。旋钮会对你拖动的速度做出反应，所以如果你缓慢移动鼠标，就能进行精确调整。2. 旋转模式：抓住旋钮的箭头并绕圈拖动。",
