    "def": "用于恢复被撤销的操作，重新执行之前的更改。",
    "example": "例子：撤销了一次调整后点击 Redo，刚才的调整重新生效。",
    "context": "The Undo, Redo, A/B and Copy buttons at the top of the plug-in interface enable you to undo your changes and switch between different states of the plug-in. Finally, the Help menu provides access to help and version information. See Loading presets and Undo, redo, A/B switch. Next: Knobs See Also Quick start Dynamics controls Time controls Knobs It is easy to control FabFilter Pro-C 2's parameters with the large round knobs. They will light up when you move the mouse cursor around to indicate that you can adjust them.",
    "contextZh": "插件界面顶部的撤销、重做、A/B 和复制按钮，让你可以撤销所做的更改，并在插件的不同状态之间切换。最后，帮助菜单提供帮助和版本信息的访问入口。参见「加载预设」和「撤销、重做、A/B 切换」。下一节：旋钮。另请参见：快速入门、动态控制、时间控制、旋钮。使用大圆形旋钮可以轻松控制 FabFilter Pro-C 2 的各项参数。当你在周围移动鼠标光标时，它们会亮起，表示你可以对它们进行调节。",
