    "context": "Tips To reset a knob to its default position, hold down the Ctrl key (Windows) or Command key (macOS) and click the knob once. Note: In Pro Tools, Pro-C 2 uses the default Pro Tools keyboard shortcut for reset: Alt+click. To fine-tune a value when using vertical drag mode or the mouse wheel, hold down the Shift key while dragging or moving the mouse wheel. Note: In Pro Tools, Pro-C 2 uses the default Pro Tools keyboard shortcut for fine tune: Ctrl+drag on Windows or Command+drag on macOS. There are several handy shortcuts in text entry mode.",
