    "zh": "循环侧链电平表",
    "def": "一种围绕旋钮显示的环形电平指示器，用于实时展示侧链信号的强度。",
    "example": "例子：Threshold 旋钮周围一圈随信号强弱亮起的环形指示灯。",
    "context": "The circular side-chain level meter around the Threshold knob shows the level of the filtered and possibly stereolinked signal that is used for detection. This feedback makes it a lot easier to choose a proper Threshold setting. Using the Audition Triggering button, at the left top of the Threshold button, you can hear on which parts of the audio Pro-C 2 is triggering and how much compression is taking place. This helps you choose an appropriate Threshold level as well, making sure Pro-C 2 catches the necessary peaks.",
    "contextZh": "Threshold 旋钮周围的循环侧链电平表显示用于检测的、经过滤波且可能经过立体声联动的信号电平。这种反馈使得选择合适的 Threshold 设置变得容易得多。使用 Threshold 按钮左上方的试听触发按钮，你可以听到 Pro-C 2 在音频的哪些部分触发以及正在进行多少压缩。这同样有助于你选择合适的 Threshold 电平，确保 Pro-C 2 能捕捉到必要的峰值。",
