    "contextZh": "Threshold 旋钮周围的循环侧链电平表显示用于检测的、经过滤波且可能经过立体声联动的信号电平。这种反馈使得选择合适的 Threshold 设置变得容易得多。使用 Threshold 按钮左上方的试听触发按钮，你可以听到 Pro-C 2 在音频的哪些部分触发以及正在进行多少压缩。这同样有助于你选择合适的 Threshold 电平，确保 Pro-C 2 能捕捉到必要的峰值。",
