    "context": "The various compression characteristics of Pro-C 2 use different release models, and in most cases, the release time is very program dependent. This means that Pro-C 2 recovers very quickly from compression after a transient, and quite slowly after longer periods of gain reduction. Note: When Auto Release is used, the Release knob will adjust the overall effect of the auto release feature on the release time. The Auto Release button (the AUTO label next to RELEASE) enables a smart auto release feature.",
