    "def": "极短的起音时间，表示压缩器几乎瞬间响应。",
    "example": "例子：0.005 ms 的起音时间适用于需要紧致控制的瞬态信号。",
    "context": "The Attack knob determines how fast compression will kick in, ranging from 0.005 ms (very fast) to 250 ms (very slow). For transient-rich program material like drums, fast attack times are needed to minimize overshoot. For other program material, too short attack times may dull the sound or introduce audible distortion. FabFilter Pro-C 2 is capable of very fast attack times and they are program dependent. The Release knob sets the time that the compressor takes to recover from gain reduction.",
    "contextZh": "起音旋钮决定压缩器启动的速度，范围从 0.005 毫秒（非常快）到 250 毫秒（非常慢）。对于鼓这类瞬态丰富的节目素材，需要快起音时间来最小化过冲。对于其他节目素材，过短的起音时间可能使声音变沉闷或引入可闻失真。FabFilter Pro-C 2 能够实现非常快的起音时间，且这些时间具有节目依赖性。释放旋钮设定压缩器从增益衰减中恢复所需的时间。",
    "category": "其他",
    "source": "小赫转存",
