    "context": "Next: Side chain section See Also Dynamics controls Using FabFilter Pro-C 2 Side chain section Click the Side Chain Expert button (centered under the main panel with compressor controls), to enable or disable the advanced side chain features, like stereo linking, M/S processing and side-chain EQ'ing. The Side Chain Expert button globally enables or disables the side chain section. To avoid surprises, the side chain settings are only in effect when the side chain section is visible.",
