    "context": "The In/Ext buttons choose between the internal, normal plug-in input, or the external side chain input. For more information on connecting the external side chain in various hosts, see External side chaining. The Audition button lets you listen to the filtered and stereo-linked signal that will be used to trigger compression. You can turn Audition mode on or off with a single click, but you can also click-and-hold the button to temporarily audition the trigger signal.",
