    "def": "指将左右两个声道的处理参数关联起来，使它们同步变化。联动程度越高，两个声道的增益衰减越趋于一致。",
    "example": "例子：在压缩器中，100% 联动意味着左右声道始终施加相同的压缩量。",
    "context": "Stereo linking and M/S processing The Stereo Link slider sets the amount of stereo linking for the trigger input signal, and also selects between normal stereo processing or mid-only/side-only processing. The first half of the slider range sets stereo linking from 0% (fully unlinked, channels operate independently) up to 100% (fully linked, resulting in the same gain reduction for both channels).",
    "contextZh": "立体声联动与中侧处理。立体声联动滑块用于设定触发输入信号的立体声联动程度，同时也可在普通立体声处理与仅中间/仅两侧处理之间进行选择。滑块范围的前半段将立体声联动从 0%（完全未联动，声道独立运作）设定到 100%（完全联动，两个声道产生相同的增益衰减）。",
    "category": "其他",
    "source": "小赫转存",
