    "example": "例子：将音量滑块向右拖动以增大音量。",
    "context": "With the slider all the way to the right, this will be the result: Mid - Only trigger on, and apply compression to, the mid signal. Side - Only trigger on, and apply compression to, the side signal. M>S - Trigger on the mid signal but only apply compression to the side signal. S>M - Trigger on the side signal but only apply compression to the mid signal. M/S processing can be very useful, especially during mastering.",
    "contextZh": "将滑块一直推到最右边，将会得到以下结果：Mid — 仅以中置信号为触发源，并对其施加压缩。Side — 仅以侧信号为触发源，并对其施加压缩。M>S — 以中置信号为触发源，但仅对侧信号施加压缩。S>M — 以侧信号为触发源，但仅对中置信号施加压缩。中侧处理非常实用，尤其是在母带处理阶段。",
