    "context": "By dragging the slider further, Pro-C 2 will eventually process only the mid-signal (mono content of the processed audio), or only the side-signal (stereo content of the processed audio). If you'd like to learn more about mid/side processing and its various uses, check out our Mid Side Demystified video tutorial by Dan Worrall. Using the small Stereo Link Mode button at the right bottom of the Stereo Link slider, you can choose between four options.",
