    "context": "For example, bass or lead vocals are often placed in the center of the stereo image, so only processing the mid-signal will leave all stereo content untouched, ensuring the most transparent end result possible. To better understand the working of these settings, enable the Audition button. You can now directly hear the effect of stereo linking and mid-only or side-only processing! Side chain EQ controller The large interactive EQ controller takes up most of the side chain section, and enables you to easily adjust the side chain filtering.",
    "contextZh": "例如，低音或主唱通常被放置在立体声像的中央，因此只处理中间信号将不会影响任何立体声内容，从而确保尽可能最通透的最终效果。为了更好地理解这些设置的工作方式，请启用试听按钮。现在你可以直接听到立体声联动以及仅中间信号或仅两侧信号处理的效果！侧链均衡控制器：大型交互式均衡控制器占据了侧链部分的大部分区域，使你能够轻松调整侧链滤波。",
