    "zh": "按住 Shift 键",
    "def": "指示用户在执行下一步操作时保持按下 Shift 键。",
    "example": "例子：按住 Shift 键并点击，以选择连续范围。",
    "context": "Hold down Shift and click a dot to select a consecutive range of bands. Deselect all bands by clicking anywhere on on the display background. Adjusting and editing bands Once you have one or more side chain EQ bands selected, the display highlights the shapes of the selected bands. Now you can simply make adjustments by dragging them around: Click and drag a selected dot to adjust the frequency of the selected bands (and the gain of the customizable mid band). Use the mouse wheel to adjust the Q setting of the mid band, making them narrower or wider.",
    "contextZh": "按住 Shift 键并点击一个点，以选择一段连续的频段。点击显示区域的任意空白处即可取消选择所有频段。调整和编辑频段：当你选中了一个或多个侧链均衡器频段后，显示区域会高亮所选频段的形状。现在你可以直接通过拖动它们来进行调整：点击并拖动一个已选中的点，以调整所选频段的频率（以及可自定义中频段的增益）。使用鼠标滚轮来调整中频段的 Q 值，使其变窄或变宽。",
