    "contextZh": "当你关闭中频滤波器的自动模式后，你可以自由调整其频率、增益、Q 值和形状（钟形、低架、高架、带通、陷波或倾斜），并通过侧链均衡控制器直接控制它。你可以用多种方式与显示界面交互：选择频段时，点击均衡频段的圆点或其周围的彩色区域即可选中它。在显示背景上点击并拖动，通过拖出一个矩形框来选中相邻频段。按住 Ctrl（Mac OS X 上为 Command）并点击另一个圆点，可以选中多个频段。",
