    "def": "MIDI 音符是 MIDI 数据中表示音高、时值和力度的信息单位，常用于触发乐器或控制参数。",
    "example": "例子：在钢琴卷帘中画一个 C4 音符，就会发送一条 MIDI Note On 消息。",
    "context": "Compression is also triggered by MIDI notes. If at least one note is on, the compressor behaves as if a 0 dB signal is entering the side chain at this moment, so it is strongly triggered. The Disable/Enable MIDI option in the MIDI Learn menu turns this off as well. Next: Displays and metering See Also Using FabFilter Pro-C 2 Dynamics controls Time controls Displays and metering FabFilter Pro-C 2 features a large animated level display with an optional knee display on top of it, and precise input, gain reduction and output metering.",
