    "context": "Note that knee display, level display and level meters all use the same meter scale, which makes it easier than ever to find the proper compression settings. The scale can be adjusted using the meter scale button at the right bottom of the interface (next to the level meters). Once you've chosen a setting, new instances of the plug-in will always open with the selected meter scale. Level display The top part of Pro-C 2 is actually a large animated level display, with the main compression controls panel floating above it.",
