    "context": "Click at the top of a meter to reset its clipping indication. Next: Oversampling See Also Dynamics controls Input and output options Using FabFilter Pro-C 2 Oversampling The dynamics algorithms often need to make very quick changes to the audio when applying gain change. These sudden changes can introduce a small amount of aliasing, which causes distortion and generally reduces the quality of the audio signal.",
    "contextZh": "点击电平表顶部即可重置其削波指示。下一项：过采样。另请参阅：动态控制、输入与输出选项、使用 FabFilter Pro-C 2。过采样：动态处理算法在施加增益变化时，往往需要对音频进行非常快速的改变。这些突然的变化可能引入少量混叠，从而导致失真，并通常会降低音频信号的质量。",
