    "example": "例子：将压缩比设为 10:1、阈值设为 -30 dB，属于非常激烈的压缩设置。",
    "context": "Oversampling is a way to reduce that aliasing by running the internal process at a sample rate that is two or four times higher than the host's sample rate. When should I use oversampling? You need it more when the compression is more aggressive and apparent. Usually, this is the case when using lower Attack and Release and/or higher Ratio and Range settings. Of course, in return for a reduction of possible aliasing/distortion, the plug-in will use more CPU power when using oversampling.",
    "contextZh": "过采样是一种通过以高于宿主采样率两倍或四倍的采样率运行内部处理来减少混叠的方法。我应该在什么时候使用过采样？当压缩越激烈、越明显时，你就越需要使用它。通常，这发生在使用较短的启动时间和释放时间和/或较高的压缩比和范围设置时。当然，作为减少可能出现的混叠/失真的代价，使用过采样时插件会消耗更多的 CPU 算力。",
