    "context": "Next: Full screen mode and resizing See Also Using FabFilter Pro-C 2 Dynamics controls Time controls Full Screen mode and resizing With just the click of the Full Screen button at the top right corner in the interface, FabFilter Pro-C 2 will fill up the whole computer screen so you can get the most out of the level display and make ultra-precise adjustments in the side-chain EQ controller. To exit Full Screen mode, just press Escape or click the Full Screen button again.",
