    "example": "例子：用户可以自定义界面的颜色和布局。",
    "context": "Resizing In addition to Full Screen mode, you can also customize the normal interface size using the Resize button at the right of the bottom bar. You can choose between Small, Medium (default) or Large. Once you have selected a size, it will automatically become the default size for new plug-in instances. Tips When using the VST3 plug-in, you can resize the plug-in interface by just dragging the window edges to any size you like. Of course you can always go back to one of the predefined sizes with the resize button.",
    "contextZh": "调整大小 除了全屏模式外，你还可以使用底栏右侧的调整大小按钮来自定义普通界面尺寸。你可以在小、中（默认）或大之间进行选择。一旦你选择了一个尺寸，它就会自动成为新插件实例的默认尺寸。提示 使用 VST3 插件时，你可以通过拖动窗口边缘到任意大小来调整插件界面。当然，你随时可以通过调整大小按钮回到某个预设尺寸。",
