    "context": "This lets you compensate globally for any gain added or removed by dynamics processing. The Global Bypass toggle button to the left of the Mix button bypasses the entire plugin. While most hosts already provide the ability to bypass plug-ins, our internal global bypass feature is guaranteed to correctly compensate the latency of the plug-in and it also applies soft bypassing to avoid clicks. While the plug-in is bypassed, the display dims and a red light glows in the bypass button itself.",
