    "def": "指对 FabFilter Pro-C 2 压缩器插件中各旋钮控件的操作方法。",
    "example": "例子：拖动旋钮可调整压缩比、启动时间、释放时间等参数。",
    "context": "Next: MIDI Learn See Also Using FabFilter Pro-C 2 Knobs MIDI Learn Controlling FabFilter Pro-C 2's parameters directly with MIDI is very easy using the MIDI Learn feature. With MIDI Learn, you can associate any MIDI controller with any parameter. Click the MIDI Learn button in the bottom bar to enter MIDI Learn mode. The interface dims and the parameters that can be controlled are highlighted. Each parameter has a small text balloon that displays the associated controller number. Now do the following to associate a controller number with a parameter: 1.",
    "contextZh": "接下来：MIDI 学习 另见 使用 FabFilter Pro-C 2 旋钮 MIDI 学习 使用 MIDI 学习功能，通过 MIDI 直接控制 FabFilter Pro-C 2 的参数非常简单。通过 MIDI 学习，你可以将任意 MIDI 控制器与任意参数关联起来。点击底部栏中的 MIDI 学习按钮，进入 MIDI 学习模式。界面会变暗，可控制的参数会被高亮显示。每个参数都有一个小的文字气泡，显示已关联的控制器编号。现在按以下步骤将控制器编号与参数关联起来：1.",
