    "def": "音频轨道或通道条上用于加载效果器的位置，信号按从上到下的顺序经过这些效果器。",
    "example": "例子：在插入槽中依次加载 EQ、压缩器和混响。",
    "context": "Here's how to do it in the most important hosts: Logic Pro Instead of adding FabFilter Pro-C 2 to one of the insert slots, create a new Instrument Track, and click on the Instrument slot. Then choose AU MIDI-controlled Effects > FabFilter > FF Pro-C 2. Now, the plug-in receives MIDI. To get audio into the plug-in, click the 'Side Chain' drop down menu in Logic's plug-in header and choose the actual input track. Next, you can mute that original track, so you only hear the audio through the plug-in.",
