    "context": "The only downside is that plug-ins with an external side-chain cannot use it anymore. Cubase Simply create a new MIDI track and set its output to the Pro-C 2 instance you would like to control via MIDI. Pro Tools Create a new MIDI track. From the MIDI input drop down menu, choose your MIDI device (if not already selected) and from the MIDI output drop down menu, choose FabFilter Pro-C 2 -> channel 1 for the instance you would like to control. Ableton Live First of all, create a new MIDI track.",
    "contextZh": "唯一的缺点是，带有外部侧链的插件无法再使用它了。Cubase：只需创建一个新的 MIDI 轨道，并将其输出设置为你想要通过 MIDI 控制的 Pro-C 2 实例。Pro Tools：创建一个新的 MIDI 轨道。从 MIDI 输入下拉菜单中，选择你的 MIDI 设备（如果尚未选择），然后从 MIDI 输出下拉菜单中，选择 FabFilter Pro-C 2 -> 通道 1，对应你想要控制的实例。Ableton Live：首先，创建一个新的 MIDI 轨道。",
