    "zh": "沙锤 / 摇响器（打击乐）",
    "def": "它是一种无固定音高的节奏打击乐器，通过摇动使内部颗粒撞击外壳产生大量高频瞬态和噪声。调节录音距离、高通滤波或压缩器的启动/释放时间，会影响“沙沙”声的亮度、颗粒感和延音长度。",
    "example": "听觉例子：拉丁或流行节奏里持续铺底的“沙沙沙”声，像细盐粒在木质或金属壳内跳动，给律动增加推动感。",
