    "def": "一种通过琴键敲击琴弦、再由拾音器拾音的机电键盘乐器，音色极短促、打击感强，带有明显的\"哇\"声质感。Stevie Wonder 的《Superstition》是其最著名的代表，常用于 funk 节奏演奏。",
