    "def": "指西方古典音乐传统，涵盖巴洛克、古典主义、浪漫主义等时期，也常作为音色标签表示\"原声、管弦、正式\"的风格取向。在制作中用作音色分类时，通常意味着使用原声乐器采样而非电子合成。",
