      {
        "word": "The right part of the main compressor settings panel contains the controls that affect the smoothing and curve shape of the gain change signal, and the wet/dry mixing controls.",
        "zh": "主压缩器设置面板的右侧包含影响增益变化信号平滑度与曲线形状的控制项，以及干湿混合控制。"
      }
