    "text": "Next: Full screen mode and resizing See Also Using FabFilter Pro-C 2 Dynamics controls Time controls Full Screen mode and resizing With just the click of the Full Screen button at the top right corner in the interface, FabFilter Pro-C 2 will fill up the whole computer screen so you can get the most out of the level display and make ultra-precise adjustments in the side-chain EQ controller. To exit Full Screen mode, just press Escape or click the Full Screen button again.",
    "translation": "接下来：全屏模式与调整窗口大小 另请参阅 使用 FabFilter Pro-C 2 动态控制 时间控制 全屏模式与调整窗口大小 只需点击界面右上角的全屏按钮，FabFilter Pro-C 2 就会铺满整个电脑屏幕，这样您就能充分利用电平显示，并在侧链均衡控制器中进行超精细调整。要退出全屏模式，只需按下 Escape 键或再次点击全屏按钮即可。",
