    "text": "Next: MIDI Learn See Also Using FabFilter Pro-C 2 Knobs MIDI Learn Controlling FabFilter Pro-C 2's parameters directly with MIDI is very easy using the MIDI Learn feature. With MIDI Learn, you can associate any MIDI controller with any parameter. Click the MIDI Learn button in the bottom bar to enter MIDI Learn mode. The interface dims and the parameters that can be controlled are highlighted. Each parameter has a small text balloon that displays the associated controller number. Now do the following to associate a controller number with a parameter: 1.",
